function distinctOnLatest(rows){
  // emulate: DISTINCT ON (user_id) * ORDER BY user_id, created_at DESC
  const sorted = [...rows].sort((a,b) => a.user_id < b.user_id ? -1 : a.user_id > b.user_id ? 1 : 0);
  const seen = new Set();
  const out = [];
  for (const r of sorted){
    if (seen.has(r.user_id)) continue;
    seen.add(r.user_id);
    out.push(r);
  }
  return out.sort((a,b)=>a.user_id<b.user_id?-1:1);
}
this.distinctOnLatest = distinctOnLatest;

